mapper.select:
SELECT 
FROM book b
JOIN book_category c ON c.id = b.category_id
LEFT JOIN book_category pc ON pc.id = c.parent_id

    AND b.id = #{query.id}
    AND b.category_id = #{query.categoryId}
    AND (b.title LIKE CONCAT('%',#{query.keyword},'%') OR b.subtitle LIKE CONCAT('%',#{query.keyword},'%') OR b.author LIKE CONCAT('%',#{query.keyword},'%') OR b.isbn LIKE CONCAT('%',#{query.keyword},'%') OR b.publisher LIKE CONCAT('%',#{query.keyword},'%'))
    AND b.title LIKE CONCAT('%',#{query.title},'%')
    AND b.subtitle LIKE CONCAT('%',#{query.subtitle},'%')
    AND b.author LIKE CONCAT('%',#{query.author},'%')
    AND b.isbn LIKE CONCAT('%',#{query.isbn},'%')
    AND b.publisher LIKE CONCAT('%',#{query.publisher},'%')
    AND b.published_date = #{query.publishedDate}
    AND b.edition LIKE CONCAT('%',#{query.edition},'%')
    AND b.language = #{query.language}
    AND b.description LIKE CONCAT('%',#{query.description},'%')
    AND b.cover_object_key = #{query.coverObjectKey}
    AND b.status = #{query.status}
    AND b.version = #{query.version}
    AND b.created_at = #{query.createdAt}
    AND b.updated_at = #{query.updatedAt}
    AND EXISTS (SELECT 1 FROM book_copy ba WHERE ba.book_id = b.id AND ba.status = 'AVAILABLE')
 ORDER BY b.id DESC
